package org.apache.commons.math3.genetics;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Collections;
import java.util.List;
import org.apache.commons.math3.exception.OutOfRangeException;
import org.apache.commons.math3.exception.util.LocalizedFormats;
import org.apache.commons.math3.util.FastMath;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for ElitisticListPopulation#setElitismRate
 */
public class ElitisticListPopulation_setElitismRate_TriageGen1Test {

    private ElitisticListPopulation population;
    private static final int POPULATION_LIMIT = 10;
    private static final double INITIAL_ELITISM_RATE = 0.5;

    @Before
    public void setUp() {
        population = new ElitisticListPopulation(POPULATION_LIMIT, INITIAL_ELITISM_RATE);
    }

    @Test
    public void testSetElitismRate_ValidValue_LowerBound() {
        double validRate = 0.0;
        population.setElitismRate(validRate);
        Assert.assertEquals("Elitism rate should be 0.0", validRate, population.getElitismRate(), 1e-9);
    }












}

